export const deleteThingsThingNameJobsJobIdExecutionNumberExecutionNumberRoute = createRoute({
  method: 'delete',
  path: '/things/{thingName}/jobs/{jobId}/executionNumber/{executionNumber}',
  description:
    '<p>Deletes a job execution.</p> <p>Requires permission to access the <a href="https://docs.aws.amazon.com/service-authorization/latest/reference/list_awsiot.html#awsiot-actions-as-permissions">DeleteJobExecution</a> action.</p>',
  operationId: 'DeleteJobExecution',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    params: z.object({
      jobId: z
        .string()
        .regex(/[a-zA-Z0-9_-]+/)
        .min(1)
        .max(64)
        .openapi({
          param: {
            name: 'jobId',
            in: 'path',
            required: true,
            description:
              'The ID of the job whose execution on a particular device will be deleted.',
            schema: { type: 'string', pattern: '[a-zA-Z0-9_-]+', minLength: 1, maxLength: 64 },
          },
        }),
      thingName: z
        .string()
        .regex(/[a-zA-Z0-9:_-]+/)
        .min(1)
        .max(128)
        .openapi({
          param: {
            name: 'thingName',
            in: 'path',
            required: true,
            description: 'The name of the thing whose job execution will be deleted.',
            schema: { type: 'string', pattern: '[a-zA-Z0-9:_-]+', minLength: 1, maxLength: 128 },
          },
        }),
      executionNumber: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'executionNumber',
            in: 'path',
            required: true,
            description:
              '<p>The ID of the job execution to be deleted. The <code>executionNumber</code> refers to the execution of a particular job on a particular device.</p> <p>Note that once a job execution is deleted, the <code>executionNumber</code> may be reused by IoT, so be sure you get and use the correct value here.</p>',
            schema: { type: 'integer' },
          },
        }),
    }),
    query: z.object({
      force: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'force',
            in: 'query',
            required: false,
            description:
              '<p>(Optional) When true, you can delete a job execution which is "IN_PROGRESS". Otherwise, you can only delete a job execution which is in a terminal state ("SUCCEEDED", "FAILED", "REJECTED", "REMOVED" or "CANCELED") or an exception will occur. The default is false.</p> <note> <p>Deleting a job execution which is "IN_PROGRESS", will cause the device to be unable to access job information or update the job execution status. Use caution and ensure that the device is able to recover to a valid state.</p> </note>',
            schema: { type: 'boolean' },
          },
        }),
      namespaceId: z
        .string()
        .regex(/[a-zA-Z0-9_-]+/)
        .exactOptional()
        .openapi({
          param: {
            name: 'namespaceId',
            in: 'query',
            required: false,
            description:
              '<p>The namespace used to indicate that a job is a customer-managed job.</p> <p>When you specify a value for this parameter, Amazon Web Services IoT Core sends jobs notifications to MQTT topics that contain the value in the following format.</p> <p> <code>$aws/things/<i>THING_NAME</i>/jobs/<i>JOB_ID</i>/notify-namespace-<i>NAMESPACE_ID</i>/</code> </p> <note> <p>The <code>namespaceId</code> feature is in public preview.</p> </note>',
            schema: { type: 'string', pattern: '[a-zA-Z0-9_-]+' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success' },
    480: {
      description: 'InvalidRequestException',
      content: { 'application/json': { schema: InvalidRequestExceptionSchema } },
    },
    481: {
      description: 'InvalidStateTransitionException',
      content: { 'application/json': { schema: InvalidStateTransitionExceptionSchema } },
    },
    482: {
      description: 'ResourceNotFoundException',
      content: { 'application/json': { schema: ResourceNotFoundExceptionSchema } },
    },
    483: {
      description: 'ThrottlingException',
      content: { 'application/json': { schema: ThrottlingExceptionSchema } },
    },
    484: {
      description: 'ServiceUnavailableException',
      content: { 'application/json': { schema: ServiceUnavailableExceptionSchema } },
    },
  },
})

