export const putThingGroupsUpdateThingGroupsForThingRoute = createRoute({
  method: 'put',
  path: '/thing-groups/updateThingGroupsForThing',
  description:
    '<p>Updates the groups to which the thing belongs.</p> <p>Requires permission to access the <a href="https://docs.aws.amazon.com/service-authorization/latest/reference/list_awsiot.html#awsiot-actions-as-permissions">UpdateThingGroupsForThing</a> action.</p>',
  operationId: 'UpdateThingGroupsForThing',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              thingName: z
                .string()
                .regex(/[a-zA-Z0-9:_-]+/)
                .min(1)
                .max(128)
                .exactOptional()
                .openapi({ description: 'The thing whose group memberships will be updated.' }),
              thingGroupsToAdd: z
                .array(ThingGroupNameSchema)
                .exactOptional()
                .openapi({ description: 'The groups to which the thing will be added.' }),
              thingGroupsToRemove: z
                .array(ThingGroupNameSchema)
                .exactOptional()
                .openapi({ description: 'The groups from which the thing will be removed.' }),
              overrideDynamicGroups: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Override dynamic thing groups with static thing groups when 10-group limit is reached. If a thing belongs to 10 thing groups, and one or more of those groups are dynamic thing groups, adding a thing to a static group removes the thing from the last dynamic group.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: UpdateThingGroupsForThingResponseSchema } },
    },
    480: {
      description: 'InvalidRequestException',
      content: { 'application/json': { schema: InvalidRequestExceptionSchema } },
    },
    481: {
      description: 'ThrottlingException',
      content: { 'application/json': { schema: ThrottlingExceptionSchema } },
    },
    482: {
      description: 'InternalFailureException',
      content: { 'application/json': { schema: InternalFailureExceptionSchema } },
    },
    483: {
      description: 'ResourceNotFoundException',
      content: { 'application/json': { schema: ResourceNotFoundExceptionSchema } },
    },
  },
})

